<?php

/*
| Data tools: bulk exports (direct and queued), the employee import and the REST API.
| See README "Data tools" and docs/API.md.
*/

return [

    'exports' => [
        // Filesystem disk and directory of the files generated by queued exports
        // (storage/app/exports on the default "local" disk).
        'disk' => env('EXPORTS_DISK', 'local'),
        'directory' => 'exports',

        // CSV / XLSX exports with more rows than this are generated by the queue worker
        // ("My exports") instead of being downloaded directly. PDFs above
        // EmployeeExportService::PDF_LIMIT (1,000 rows) are always queued.
        'queue_threshold' => (int) env('EXPORTS_QUEUE_THRESHOLD', 20000),

        // Maximum rows of a queued PDF; a larger selection is cut off (noted in the PDF).
        'queued_pdf_limit' => (int) env('EXPORTS_QUEUED_PDF_LIMIT', 5000),

        // Queue (connection default) the export jobs are pushed to.
        'queue' => env('EXPORTS_QUEUE', 'default'),

        // Generated files and their list entries are deleted after this many days
        // (`php artisan exports:prune`, scheduled daily).
        'retention_days' => (int) env('EXPORTS_RETENTION_DAYS', 7),
    ],

    'imports' => [
        // Data rows per file (the header row not counted) and upload size in kilobytes.
        'max_rows' => (int) env('IMPORTS_MAX_ROWS', 5000),
        'max_file_kb' => (int) env('IMPORTS_MAX_FILE_KB', 5120),

        // How long a validated upload waits for its confirmation (minutes).
        'preview_ttl' => (int) env('IMPORTS_PREVIEW_TTL', 60),
    ],

    'api' => [
        // Requests per minute and token (per IP address before authentication).
        'rate_limit' => (int) env('API_RATE_LIMIT', 60),

        'default_per_page' => 20,
        'max_per_page' => 100,

        // Personal access tokens per user.
        'max_tokens' => 20,
    ],

];
